def visit_subscript(self, node: nodes.Subscript) -> None:
    inferred = safe_infer(node.value)
    if (  # pylint: disable=too-many-boolean-expressions
        isinstance(inferred, nodes.ClassDef)
        and (
            inferred.qname() in {"typing.Generator", "typing.AsyncGenerator"}
            and self._py313_plus
            or inferred.qname()
            in {"_collections_abc.Generator", "_collections_abc.AsyncGenerator"}
        )
        and isinstance(node.slice, nodes.Tuple)
        and all(
            (isinstance(el, nodes.Const) and el.value is None)
            for el in node.slice.elts[1:]
        )
    ):
        suggested_str = (
            f"{node.value.as_string()}[{node.slice.elts[0].as_string()}]"
        )
        self.add_message(
            "unnecessary-default-type-args",
            args=(node.as_string(), suggested_str),
            node=node,
            confidence=HIGH,
        )

def visit_asyncwith(self, node: nodes.AsyncWith) -> None:
    for ctx_mgr, _ in node.items:
        inferred = checker_utils.safe_infer(ctx_mgr)
        if inferred is None or isinstance(inferred, util.UninferableBase):
            continue

        if isinstance(inferred, nodes.AsyncFunctionDef):
            # Check if we are dealing with a function decorated
            # with contextlib.asynccontextmanager.
            if decorated_with(inferred, self._async_generators):
                continue
        elif isinstance(inferred, astroid.bases.AsyncGenerator):
            # Check if we are dealing with a function decorated
            # with contextlib.asynccontextmanager.
            if decorated_with(inferred.parent, self._async_generators):
                continue
        else:
            try:
                inferred.getattr("__aenter__")
                inferred.getattr("__aexit__")
            except astroid.exceptions.NotFoundError:
                if isinstance(inferred, astroid.Instance):
                    # If we do not know the bases of this class,
                    # just skip it.
                    if not checker_utils.has_known_bases(inferred):
                        continue
                    # Ignore mixin classes if they match the rgx option.
                    if (
                        "not-async-context-manager"
                        in self.linter.config.ignored_checks_for_mixins
                        and self._mixin_class_rgx.match(inferred.name)
                    ):
                        continue
            else:
                continue
        self.add_message(
            "not-async-context-manager", node=node, args=(inferred.name,)
        )

def get_match_args_for_class(node: nodes.NodeNG) -> list[str] | None:
    """Infer __match_args__ from class name."""
    inferred = safe_infer(node)
    if not isinstance(inferred, nodes.ClassDef):
        return None
    try:
        match_args = inferred.getattr("__match_args__")
    except astroid.exceptions.NotFoundError:
        return None

    match match_args:
        case [
            nodes.AssignName(parent=nodes.Assign(value=nodes.Tuple(elts=elts))),
            *_,
        ] if all(
            isinstance(el, nodes.Const) and isinstance(el.value, str) for el in elts
        ):
            return [el.value for el in elts]
        case _:
            return None

def visit_matchclass(self, node: nodes.MatchClass) -> None:
    attrs: set[str] = set()
    dups: set[str] = set()

    if (
        node.patterns
        and (match_args := self.get_match_args_for_class(node.cls)) is not None
    ):
        if len(node.patterns) > len(match_args):
            self.add_message(
                "too-many-positional-sub-patterns",
                node=node,
                args=(node.cls.as_string(), len(match_args), len(node.patterns)),
                confidence=INFERENCE,
            )
            return

        for i in range(len(node.patterns)):
            name = match_args[i]
            self.check_duplicate_sub_patterns(name, node, attrs=attrs, dups=dups)

    for kw_name in node.kwd_attrs:
        self.check_duplicate_sub_patterns(kw_name, node, attrs=attrs, dups=dups)
